import configparser

def load(path='config.ini'):
    c = configparser.ConfigParser()
    c.read(path)
    return {k: _coerce(v) for k, v in c['features'].items()}

def _coerce(v):
    if v.isdigit():
        return int(v)
    return bool(v)

