from text import words

def top_words(s, n=2):
    counts = {}
    for w in words(s.lower()):
        counts[w] = counts.get(w, 0) + 1
    ranked = sorted(counts.items(), key=lambda kv: kv[1])
    return [w for w, _ in ranked[:n]]

